<div class="form-grid"><div class="field"><label for="provider_number">Provider number</label><input id="provider_number" name="provider_number" value="{{ old('provider_number', $provider->provider_number) }}" required></div><div class="field"><label for="name">Name</label><input id="name" name="name" value="{{ old('name', $provider->name) }}" required></div><div class="field"><label for="email">Email</label><input id="email" type="email" name="email" value="{{ old('email', $provider->email) }}"></div><div class="field"><label for="phone">Phone</label><input id="phone" name="phone" value="{{ old('phone', $provider->phone) }}"></div><div class="field full"><label for="address">Provider address</label><input id="address" name="address" value="{{ old('address', $provider->address) }}" placeholder="e.g. Cairo, Egypt"><small class="muted">Enter the normal address, then select the exact location below.</small></div><div class="field full provider-location-picker"><label>Provider location on map</label><div class="location-picker-help">Click the map or drag the pin to the provider location. This is used to show assigned classes on the operational map.</div><div id="providerLocationMap" class="provider-location-map" data-lat="{{ old('latitude', $provider->latitude) }}" data-lng="{{ old('longitude', $provider->longitude) }}"></div><div class="location-picker-actions"><button class="btn secondary" type="button" id="clearProviderLocation">Clear location</button><span id="providerLocationMessage" class="muted" role="status">No map location selected.</span></div><input id="latitude" type="hidden" name="latitude" value="{{ old('latitude', $provider->latitude) }}"><input id="longitude" type="hidden" name="longitude" value="{{ old('longitude', $provider->longitude) }}"></div></div><div class="actions" style="margin-top:20px"><button class="btn">Save provider</button><a class="btn secondary" href="{{ $provider->exists ? route('admin.providers.show', $provider) : route('admin.providers.index') }}">Cancel</a></div>
